function renderColumn(b,c){const all=visibleTasks(b,c.id),key=`${b.id}:${c.id}`,limit=renderLimits.get(key)||PAGE_SIZE,shown=all.slice(0,limit);return`<section class="column ${c.id===state.activeColumnId?'active':''}" data-column="${esc(c.id)}"><header class="column-head"><h2>${esc(c.title)} <small>${all.length}</small></h2><button class="column-add" type="button" data-add-column-task="${esc(c.id)}" aria-label="Nueva tarea en ${esc(c.title)}">＋</button></header><div class="task-list" data-list="${esc(c.id)}">${shown.length?shown.map(renderCard).join(''):`<div class="empty">Nada aquí.</div>`}${all.length>limit?`<button type="button" class="more-button" data-more="${esc(c.id)}">Mostrar ${Math.min(PAGE_SIZE,all.length-limit)} más · ${all.length-limit} restantes</button>`:''}</div></section>`}
function renderCard(t){const p=person(t.assignee),progress=t.subtasks.length?`${t.subtasks.filter(s=>s.done).length}/${t.subtasks.length}`:'';return`<article class="task-card" draggable="true" tabindex="0" role="button" data-task="${esc(t.id)}" data-priority="${t.priority}" aria-label="Abrir ${esc(t.title)}"><span class="task-title">${esc(t.title)}</span>${t.description?`<span class="task-desc">${esc(t.description)}</span>`:''}<div class="task-foot"><div class="task-meta">${t.tags.slice(0,3).map(x=>`<span class="tag">${esc(x)}</span>`).join('')}${progress?`<span class="tiny-meta">☑ ${progress}</span>`:''}${t.comments.length?`<span class="tiny-meta">◦ ${t.comments.length}</span>`:''}</div>${p?`<span class="avatar" title="${esc(p.name)}">${esc(p.initials)}</span>`:''}</div></article>`}
function renderBoardPicker(){const active=currentBoard();$('#board-list').innerHTML=state.boards.map(b=>`<div class="board-row ${b.id===active.id?'active':''}"><button type="button" data-board="${esc(b.id)}"><strong>${esc(b.title)}</strong><small>${b.tasks.length.toLocaleString('es-CL')} tareas · ${b.columns.length} columnas</small></button></div>`).join('')}
function renderQa(){const b=currentBoard(),subs=b.tasks.reduce((n,t)=>n+t.subtasks.length,0),comments=b.tasks.reduce((n,t)=>n+t.comments.length,0);$('#qa-kpis').innerHTML=`<div class="qa-kpi"><strong>${b.tasks.length.toLocaleString('es-CL')}</strong><span>tareas</span></div><div class="qa-kpi"><strong>${subs.toLocaleString('es-CL')}</strong><span>subtareas</span></div><div class="qa-kpi"><strong>${comments.toLocaleString('es-CL')}</strong><span>comentarios</span></div>`}
function openDialog(id){const d=$(`#${id}`);if(!d.open)d.showModal()}
function closeDialog(target){const d=typeof target==='string'?$(`#${target}`):target;if(d?.open)d.close()}
function openQuick(colId){const b=currentBoard();$('#quick-title').value='';$('#quick-status').innerHTML=b.columns.map(c=>`<option value="${esc(c.id)}">${esc(c.title)}</option>`).join('');$('#quick-status').value=colId&&b.columns.some(c=>c.id===colId)?colId:state.activeColumnId;openDialog('quick-dialog');setTimeout(()=>$('#quick-title').focus(),0)}
function createTask(title,status){const b=currentBoard();const order=b.tasks.filter(t=>t.status===status).length;const task={id:uid('task'),title:title.trim(),description:'',status,assignee:'',priority:'normal',tags:[],subtasks:[],comments:[],order,updated:nowIso()};commit('Crear tarea',()=>b.tasks.push(task),'Tarea creada');return task}
function openTask(id){const t=taskById(id);if(!t)return;activeTaskId=id;const b=currentBoard();$('#task-title').value=t.title;$('#task-description').value=t.description;$('#task-status').innerHTML=b.columns.map(c=>`<option value="${esc(c.id)}">${esc(c.title)}</option>`).join('');$('#task-status').value=t.status;$('#task-assignee').innerHTML=`<option value="">Sin responsable</option>${people.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}`;$('#task-assignee').value=t.assignee;$('#task-priority').value=t.priority;renderTaskTags(t);renderSubtasks(t);renderComments(t);$('#save-state').textContent='Guardado';autoSize($('#task-title'));autoSize($('#task-description'));openDialog('task-dialog')}
